package com.mall.controller.admin;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.mall.common.result.Result; import com.mall.entity.InventoryLog; import com.mall.entity.SeckillRequest; import com.mall.mapper.InventoryLogMapper; import com.mall.mapper.SeckillRequestMapper; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.Map;
@RestController @RequestMapping("/api/admin/operations/health") public class AdminOperationsHealthController { private final InventoryLogMapper inventory; private final SeckillRequestMapper seckill; public AdminOperationsHealthController(InventoryLogMapper inventory,SeckillRequestMapper seckill){this.inventory=inventory;this.seckill=seckill;} @GetMapping public Result<Map<String,Object>> health(){long failedInventory=inventory.selectCount(new LambdaQueryWrapper<InventoryLog>().eq(InventoryLog::getStatus,2));long staleSeckill=seckill.selectCount(new LambdaQueryWrapper<SeckillRequest>().eq(SeckillRequest::getStatus,0).lt(SeckillRequest::getCreateTime,LocalDateTime.now().minusMinutes(5)));return Result.success(Map.of("failedInventoryReleases",failedInventory,"staleSeckillRequests",staleSeckill,"checkedAt",LocalDateTime.now(),"healthy",failedInventory==0&&staleSeckill==0));} }
